function draw({board,width,height,params}) {
 const beta=params.beta, t=params.t, blue='#287d99', orange='#b65a31', ink='#253941', muted='#677b84';
 const raw=1-Math.pow(beta,t), mass=raw, corrected=raw/mass;
 board.text('condition','恒定梯度 g=1 · v₀=0',18,20,{size:14,color:muted});
 board.line('legend-raw',18,45,36,45,blue,2.5);
 board.text('legend-raw-text','原始 v',43,49,{size:14,color:blue});
 board.line('legend-corrected',150,45,168,45,orange,2.5);
 board.text('legend-corrected-text','校正后 v̂',175,49,{size:14,color:orange});
 const f=board.axes('mean-axes',{xDomain:[0,50],yDomain:[0,1.15],xLabel:'步数 t',yLabel:'估计值',box:[48,84,width-22,height-80],grid:true});
 const curve=Array.from({length:51},(_,i)=>{const x=i;return [x,1-Math.pow(beta,x)];});
 board.curve('raw-curve',f,curve,{color:blue,width:2.5});
 board.curve('corrected-curve',f,[[1,1],[50,1]],{color:orange,width:2.5});
 board.line('selected-gap',f.x(t),f.y(raw),f.x(t),f.y(1),muted,1.5,.6);
 board.circle('selected-raw',f.x(t),f.y(raw),4.5,blue);
 board.circle('selected-corrected',f.x(t),f.y(1),4.5,orange);
 board.text('raw-number','t='+t+'：v='+raw.toFixed(4),18,height-30,{size:14,color:blue});
 board.text('mass-number','权重和='+mass.toFixed(4)+' → 校正后=1',18,height-8,{size:14,color:ink});
 return {beta,t,gradient:1,initial:0,raw,mass,corrected,missingMass:Math.pow(beta,t),curve,convention:'整数步执行EWMA；曲线在整数步之间仅作连线显示，t=0的校正未定义'};
}

function draw({board,width,height,params}) {
 const q=params.q, s=params.s, beta=.9, a=1-beta, blue='#287d99', orange='#b65a31', muted='#677b84', ink='#253941';
 const da=a*(q-s), dy=a*q*Math.sign(q-s);
 board.text('condition','单坐标 · q=g² · β₂=0.9',18,20,{size:14,color:muted});
 board.line('adam-legend',18,45,36,45,blue,2.5);
 board.text('adam-label','Adam',43,49,{size:14,color:blue});
 board.line('yogi-legend',150,45,168,45,orange,2.5);
 board.text('yogi-label','Yogi',175,49,{size:14,color:orange});
 const f=board.axes('delta-axes',{xDomain:[0,4],yDomain:[-.25,.45],xLabel:'当前 q=g²',yLabel:'变化 Δs',box:[52,84,width-22,height-90],grid:true});
 board.line('zero-guide',f.x(0),f.y(0),f.x(4),f.y(0),muted,1,.4);
 board.curve('adam-line',f,[[0,-a*s],[4,a*(4-s)]],{color:blue,width:2.5});
 board.curve('yogi-left',f,[[0,0],[s,-a*s]],{color:orange,width:2.5});
 board.curve('yogi-right',f,[[s,a*s],[4,4*a]],{color:orange,width:2.5});
 for(const sign of [-1,1]) board.mark('open-'+sign,'circle',{cx:f.x(s),cy:f.y(sign*a*s),r:4,fill:'#faf9f6',stroke:orange,'stroke-width':2});
 board.circle('yogi-equal',f.x(s),f.y(0),3,orange);
 board.line('selection',f.x(q),f.y(-.25),f.x(q),f.y(.45),muted,1,.25);
 board.circle('selected-adam',f.x(q),f.y(da),5,blue);
 board.mark('selected-yogi','circle',{cx:f.x(q),cy:f.y(dy),r:6,fill:'none',stroke:orange,'stroke-width':2});
 board.text('adam-value','Adam：s′='+(s+da).toFixed(3)+'  (Δ '+da.toFixed(3)+')',18,height-50,{size:14,color:blue});
 board.text('yogi-value','Yogi：s′='+(s+dy).toFixed(3)+'  (Δ '+dy.toFixed(3)+')',18,height-28,{size:14,color:orange});
 board.text('equal-note','空心端点不取；q=s 时 Δs=0',18,height-6,{size:13,color:muted});
 return {q,previousSquare:s,beta,adamDelta:da,yogiDelta:dy,adamNext:s+da,yogiNext:s+dy,convention:'比较一次未校正的二次矩更新；不是收敛实验，sgn(0)=0'};
}
